class Solution { vector<int> parent,size;int find(int x){return parent[x]==x?x:parent[x]=find(parent[x]);}void unite(int a,int b){a=find(a);b=find(b);if(a==b)return;if(size[a]<size[b])swap(a,b);parent[b]=a;size[a]+=size[b];}public:int numberOfGoodPaths(vector<int>& vals,vector<vector<int>>& edges){int n=vals.size();vector<vector<int>> graph(n);for(auto& edge:edges){graph[edge[0]].push_back(edge[1]);graph[edge[1]].push_back(edge[0]);}vector<int> order(n);iota(order.begin(),order.end(),0);sort(order.begin(),order.end(),[&](int a,int b){return vals[a]<vals[b];});parent.resize(n);iota(parent.begin(),parent.end(),0);size.assign(n,1);vector<bool> active(n);int answer=n;for(int start=0;start<n;){int end=start;while(end<n&&vals[order[end]]==vals[order[start]])++end;for(int p=start;p<end;++p){int node=order[p];active[node]=true;for(int next:graph[node])if(active[next])unite(node,next);}unordered_map<int,int> count;for(int p=start;p<end;++p)++count[find(order[p])];for(auto [root,c]:count)answer+=c*(c-1)/2;start=end;}return answer;} };
